#!/usr/bin/env python3

# this script is ran automatically; there should be no need to run this manually
#  used in .github/workflows/generate_docs.sh to generate docs/hashcat.1 on every commit to master
# example usage: ./hashcat --help | python3 hashcat-help2man.py > docs/hashcat.1
#
# The page is made from --help alone, so it says what --help says and changes when --help does. It
# carries no date and no version, which would change it on every commit.

import re
import sys


def roff_escape(text: str) -> str:
  text = text.replace("\\", "\\e")
  text = text.replace("-", "\\-")

  # a line starting with a dot or an apostrophe would be read as a request

  if text.startswith(".") or text.startswith("'"):
    text = "\\&" + text

  return text


def section_title(name: str) -> str:
  title = name.upper()

  return title


def options_section(lines: list) -> list:
  out = []

  for line in lines:
    # header and rule rows have no option in them

    if line.startswith(" Options Short / Long"):
      continue

    if line.startswith("="):
      continue

    # every row has the 4 columns, the example column empty where there is none

    cols = line.split("|")

    if len(cols) != 4:
      continue

    names = cols[0].strip()
    kind = cols[1].strip()
    desc = cols[2].strip()
    example = cols[3].strip()

    out.append(".TP")

    if len(kind) > 0:
      out.append(".B %s \" %s\"" % (roff_escape(names), roff_escape(kind)))
    else:
      out.append(".B %s" % roff_escape(names))

    out.append(roff_escape(desc))

    if len(example) > 0:
      out.append(".br")
      out.append("Example: %s" % roff_escape(example))

  return out


def plain_section(lines: list) -> list:
  out = [".nf"]

  for line in lines:
    out.append(roff_escape(line))

  out.append(".fi")

  return out


def main() -> int:
  text = sys.stdin.read().splitlines()

  usage = ""

  sections = []

  current = None

  for line in text:
    if line.endswith("starting in help mode"):
      continue

    if line.startswith("Usage: "):
      usage = line[len("Usage: "):]

      continue

    m = re.match(r"^- \[ (.+) \] -$", line)

    if m is not None:
      current = [m.group(1), []]

      sections.append(current)

      continue

    if current is None:
      continue

    current[1].append(line)

  out = []

  out.append('.\\" These docs are automatically generated by Github Actions, see .github/workflows/build.yml')
  out.append('.\\" All manual changes will be overwritten!')
  out.append('.TH HASHCAT 1 "" "hashcat" "User Commands"')

  out.append(".SH NAME")
  out.append("hashcat \\- advanced password recovery")

  out.append(".SH SYNOPSIS")

  if usage.startswith("hashcat "):
    out.append(".B hashcat")
    out.append(roff_escape(usage[len("hashcat "):]))
  else:
    out.append(roff_escape(usage))

  for name, lines in sections:
    # blank lines at either end of a section are the layout of the terminal output

    while (len(lines) > 0) and (lines[0].strip() == ""):
      lines = lines[1:]

    while (len(lines) > 0) and (lines[-1].strip() == ""):
      lines = lines[:-1]

    out.append(".SH %s" % roff_escape(section_title(name)))

    if name == "Options":
      out.extend(options_section(lines))
    else:
      out.extend(plain_section(lines))

  sys.stdout.write("\n".join(out) + "\n")

  return 0


if __name__ == "__main__":
  sys.exit(main())
